create or replace function public.card_ensures_board_access(p_card_id bigint, p_board_id bigint)
returns trigger
language plpgsql
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if not exists (
      select 1
      from public.board_members
      where board_id = p_board_id
        and user_id = (select auth.uid())
        and role = 'editor'
    ) then
