    end if;
    return new;
  end if;

  if tg_op = 'UPDATE' then
    if (select auth.uid()) is distinct from (select auth.uid()) then
      return new;
    end if;

    if not exists (
      select 1
      from public.board_members
      where board_id = p_board_id
        and user_id = (select auth.uid())
        and role = 'editor'
    ) then
      raise exception 'card % cannot be modified', p_card_id;
    end if;

    if new.board_id is distinct from p_board_id then
      if not exists (
        select 1
        from public.board_members
        where board_id = new.board_id
          and user_id = (select auth.uid())
          and role = 'editor'
      ) then
        raise exception 'card % can only be moved to boards where the user is an editor', p_card_id;
      end if;
    end if;

    return new;
  end if;

  raise exception 'invalid trigger operation';
end;
$$;

