create or replace function public.is_friend(p_user_id uuid, p_friend_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.friendships f
    where ((f.requester_id = p_user_id and f.addressee_id = p_friend_id)
          or (f.requester_id = p_friend_id and f.addressee_id = p_user_id))
      and f.status = 'accepted'
  );
$$;

create or replace function public.enforce_friendship_update()
returns trigger
language plpgsql
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.status <> 'pending' then
      raise exception 'new friendships must be pending';
    end if;
    if new.requester_id = new.addressee_id then
      raise exception 'a friendship cannot be with yourself';
    end if;
    return new;
  end if;

  if tg_op = 'UPDATE' then
    if old.requester_id <> new.requester_id or old.addressee_id <> new.addressee_id then
      raise exception 'friendship ids cannot be changed';
    end if;
    if old.status = 'accepted' then
      raise exception 'accepted friendships cannot be changed';
    end if;
    if new.status = 'accepted' and old.status <> 'pending' then
      raise exception 'only pending requests can be accepted';
    end if;
    if new.status = 'accepted' and new.requester_id = new.addressee_id then
      raise exception 'cannot accept a request from yourself';
    end if;
    return new;
  end if;

  return new;
end;
$$;

