          or (f.requester_id = p_friend_id and f.addressee_id = p_user_id))
      and f.status = 'accepted'
  );
$$;

create or replace function public.enforce_friendship_insert()
returns trigger
language plpgsql
as $$
begin
  if auth.uid() is null then
    raise exception 'friendship insert requires authenticated user';
  end if;
  if new.requester_id <> auth.uid() then
    raise exception 'you can only send friend requests as yourself';
  end if;
  if new.status <> 'pending' then
    raise exception 'new friend requests must be pending';
  end if;
  if new.requester_id = new.addressee_id then
    raise exception 'you cannot send a friend request to yourself';
  end if;
  return new;
end;
$$;

create or replace function public.enforce_friendship_update()
returns trigger
language plpgsql
as $$
begin
  if auth.uid() is null then
    raise exception 'friendship update requires authenticated user';
  end if;
  if old.status = 'accepted' then
    raise exception 'accepted friendships cannot be changed';
  end if;
  if new.status <> 'accepted' then
    raise exception 'only pending requests can be accepted';
  end if;
  if old.requester_id = auth.uid() then
    raise exception 'requesters cannot accept their own requests';
  end if;
  if old.addressee_id <> auth.uid() then
    raise exception 'only the addressee can accept a request';
  end if;
  return new;
end;
$$;

create or replace function public.enforce_post_author()
returns trigger
language plpgsql
as $$
begin
  if auth.uid() is null then
    raise exception 'post operation requires authenticated user';
  end if;
  if tg_op = 'INSERT' then
    if new.author_id <> auth.uid() then
      raise exception 'posts must be authored by the current user';
    end if;
  elsif tg_op = 'UPDATE' then
    if new.author_id <> auth.uid() then
      raise exception 'post author cannot be changed';
    end if;
  elsif tg_op = 'DELETE' then
    if old.author_id <> auth.uid() then
      raise exception 'only the post author can delete a post';
    end if;
  end if;
  return new;
end;
$$;

