create or replace function public.requests_enforce_update()
returns trigger
language plpgsql
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;
  if tg_op = 'INSERT' then
    if new.status <> 'open' then
      raise exception 'new requests must be open';
    end if;
    if new.created_by <> auth.uid() then
      raise exception 'requests must be created by the current user';
    end if;
    return new;
  end if;
  if tg_op = 'UPDATE' then
    if old.id <> new.id or old.unit_id <> new.unit_id or old.created_by <> new.created_by or old.description <> new.description then
      raise exception 'only request status may be updated';
    end if;
    if not exists (
      select 1
      from public.building_staff s
      where s.building_id = (select u.building_id from public.units u where u.id = new.unit_id)
        and s.user_id = auth.uid()
    ) then
      raise exception 'only building staff may update request status';
    end if;
    return new;
  end if;
  raise exception 'unknown trigger operation';
end;
$$;

