create policy "request_photos_select_resident_or_staff"
on public.request_photos for select to authenticated
using (public.is_resident_of_unit((select r.unit_id from public.requests r where r.id = request_photos.request_id)) or public.is_building_staff((select u.building_id from public.units u where u.id = (select r.unit_id from public.requests r where r.id = request_photos.request_id))));

create policy "requests_insert_resident"
