create or replace function public.enforce_request_insert()
returns trigger
language plpgsql
as $$
begin
  if auth.uid() is null then
    raise exception 'request insertion is not allowed';
  end if;
  if new.status <> 'open' then
    raise exception 'new requests must have status open';
  end if;
  if new.created_by <> auth.uid() then
    raise exception 'request must be created by the current user';
  end if;
  if not exists (
    select 1
    from public.residents r
    where r.unit_id = new.unit_id
      and r.user_id = auth.uid()
  ) then
    raise exception 'request must be for a unit where the current user is a resident';
  end if;
  return new;
end;
$$;

create or replace function public.enforce_request_update()
returns trigger
language plpgsql
as $$
begin
  if auth.uid() is null then
    raise exception 'request update is not allowed';
  end if;
  if old.status <> 'open' and old.status <> 'in_progress' then
    raise exception 'request % is closed', old.id;
  end if;
  if public.is_building_staff(old.unit_id) then
    if new.id <> old.id
       or new.unit_id <> old.unit_id
       or new.created_by <> old.created_by
       or new.description <> old.description then
      raise exception 'building staff can only change request status';
    end if;
  elsif public.is_unit_resident(old.unit_id) then
    if new.status <> old.status then
      raise exception 'residents cannot change request status';
    elsif new.id <> old.id
       or new.unit_id <> old.unit_id
       or new.created_by <> old.created_by
       or new.description <> old.description then
      raise exception 'residents cannot change request details';
    end if;
  else
    raise exception 'request update is not allowed';
  end if;
  return new;
end;
$$;

