create or replace function public.class_spot_immutable_columns()
returns trigger
language sql
as $$
begin
  if tg_op = 'UPDATE' then
    if old.class_id <> new.class_id or old.user_id <> new.user_id then
      raise exception 'class_spot class_id and user_id cannot be changed';
    end if;
    if new.status <> old.status then
      if old.status = 'enrolled' then
        raise exception 'enrolled spot cannot be downgraded';
      elsif new.status = 'enrolled' and (
        not exists (select 1 from public.classes c where c.id = old.class_id and c.instructor_id = auth.uid())
        or not public.class_has_capacity(old.class_id)
      ) then
        raise exception 'spot can only move to enrolled if there is room and the mover is not an instructor';
      end if;
    end if;
  end if;
  return new;
end;
$$;

