```sql
alter table public.classes enable row level security;
alter table public.class_spots enable row level security;

create or replace function public.class_has_capacity(p_class_id bigint)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.classes c
    where c.id = p_class_id
    and (select count(*) from public.class_spots s where s.class_id = c.id and s.status = 'enrolled') < c.capacity
  );
$$;

create or replace function public.class_spot_unchanged(p_class_id bigint, p_user_id uuid, p_status text)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.class_spots s
    where s.class_id = p_class_id
      and s.user_id = p_user_id
      and s.status = p_status
  );
$$;

create or replace function public.enforce_class_spot_update()
returns trigger
language plpgsql
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.user_id <> auth.uid() then
      raise exception 'class spots must be joined with your own user id';
    end if;

    if exists (
      select 1
      from public.class_spots s
      where s.class_id = new.class_id
      and s.user_id = new.user_id
    ) then
      raise exception 'already have a spot in this class';
    end if;

    if new.status = 'enrolled' then
      if not public.class_has_capacity(new.class_id) then
        raise exception 'class is full';
      end if;
    elsif new.status = 'waitlisted' then
      if exists (
        select 1
        from public.class_spots s
        where s.class_id = new.class_id
        and s.user_id = new.user_id
        and s.status = 'enrolled'
      ) then
        raise exception 'already enrolled in this class';
      end if;
    else
      raise exception 'invalid spot status';
    end if;

    return new;
  elsif tg_op = 'UPDATE' then
    if old.class_id <> new.class_id or old.user_id <> new.user_id then
      raise exception 'class spot class and user cannot change';
    end if;

    if new.status = 'enrolled' and old.status = 'waitlisted' then
      if not public.class_has_capacity(old.class_id) then
        raise exception 'class is full';
      end if;
    elsif new.status <> old.status then
      raise exception 'spot status change not allowed';
    end if;

    return new;
  else
    raise exception 'unsupported operation';
  end if;
end;
$$;

create trigger class_spots_enforce_update
before insert or update on public.class_spots
for each row execute function public.enforce_class_spot_update();

create policy "classes_select_authenticated"
on public.classes for select to authenticated
using (true);

create policy "class_spots_select_own_or_instructor"
on public.class_spots for select to authenticated
using (user_id = auth.uid() or exists (select 1 from public.classes c where c.id = class_spots.class_id and c.instructor_id = auth.uid()));

create policy "class_spots_insert_own"
on public.class_spots for insert to authenticated
with check (user_id = auth.uid() and (status = 'enrolled' and public.class_has_capacity(class_id) or status = 'waitlisted'));

create policy "class_spots_update_own_waitlisted"
on public.class_spots for update to authenticated
using (user_id = auth.uid() and status = 'waitlisted')
with check (user_id = auth.uid() and status = 'enrolled' and public.class_has_capacity(class_id));

create policy "class_spots_delete_own"
on public.class_spots for delete to authenticated
using (user_id = auth.uid());

create policy "class_spots_delete_instructor"
on public.class_spots for delete to authenticated
using (exists (select 1 from public.classes c where c.id = class_spots.class_id and c.instructor_id = auth.uid()));
